for name, z in zones.items():
    # find all lines with isPointOf z
    print("="*30, name)
    for m in re.finditer(r'(?m)(bldg:[^\s;\.,]+) a (brick:[^\s;]+) ;\n(.*?)+?brick:isPointOf bldg:'+z+r' ;\n(.*?)+?(\.) ?\n', txt):
        pass
    # simpler: find every "brick:isPointOf bldg:Z;" and get the surrounding block
    for m in re.finditer(r'brick:isPointOf bldg:'+re.escape(z)+r'\s*;', txt):
        s = txt.rfind('\n\n', 0, m.start())
        end = txt.find('.\n', m.start())
        block = txt[s:end+1]
        print(block)
        print("---")

